using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;

namespace MacroExecute
{
    internal static class DesignTests
    {
        private static void Check(bool value,string message) { if(!value)throw new Exception(message); }
        private static IEnumerable<Control> All(Control root) { foreach(Control child in root.Controls){yield return child;foreach(var nested in All(child))yield return nested;} }
        private static Button Button(Form form,string name) { return All(form).OfType<Button>().Single(b=>b.AccessibleName==name||b.Text==name); }
        private static void Click(Button button) { typeof(Control).GetMethod("OnClick",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(button,new object[]{EventArgs.Empty}); }
        private static void Render(Form form,string directory,string name) { HeadlessUi.Render(form,Path.Combine(directory,name+".png"));Check(!form.Visible,"Form was shown"); }
        private static double Luminance(Color color) { Func<byte,double> channel=v=>{double n=v/255.0;return n<=0.04045?n/12.92:Math.Pow((n+0.055)/1.055,2.4);};return 0.2126*channel(color.R)+0.7152*channel(color.G)+0.0722*channel(color.B); }
        private static double Contrast(Color a,Color b) { double x=Luminance(a),y=Luminance(b);return (Math.Max(x,y)+0.05)/(Math.Min(x,y)+0.05); }
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Action help is discoverable in the library and inspector without editing a workflow",delegate{
                using(var form=new MainForm(Samples.Nested(),null,false,false,true)){string initial=Storage.Encode(form.DocumentHeadless());Render(form,directory,"guide-entry-points");var libraryMenus=All(form).OfType<Button>().Where(b=>b.ContextMenuStrip!=null&&b.ContextMenuStrip.Items.Count==1&&b.ContextMenuStrip.Items[0].Text.StartsWith("How to use ")).ToArray();Check(libraryMenus.Length>=35,"Library action help missing");var help=Button(form,"Selected action guide");Check(help.Enabled&&help.Width>=90,"Inspector guide inaccessible");form.SearchHeadless("image");Check(All(form).OfType<Button>().Any(b=>b.ContextMenuStrip!=null&&b.ContextMenuStrip.Items.Count==1&&b.ContextMenuStrip.Items[0].Text.Contains("IF image found")),"Search results lost action help");Check(Storage.Encode(form.DocumentHeadless())==initial&&!form.Visible,"Help discovery mutated the workflow");}
            });
            test("Guide search covers field examples, preserves matching selection and follows related guides",delegate{
                using(var guide=new GuideCenter(ActionKind.IfImage)){int count=guide.TopicCount;guide.SearchHeadless("wait before deciding");Check(All(guide).OfType<ActionShowcase>().Single().Kind==ActionKind.IfImage,"Field-value search lost the matching selected guide");Click(Button(guide,"Related guide: Mouse click"));Check(guide.TopicCount==count&&All(guide).OfType<ActionShowcase>().Single().Kind==ActionKind.MouseClick,"Related guide failed to leave a filtered result set");guide.SearchHeadless("xyz-no-guide-9817");Check(guide.TopicCount==0,"Unexpected search result");Click(Button(guide,"Clear guide search"));Check(guide.TopicCount==count&&!guide.Visible,"Clear failed to restore all guides safely");}
            });
            test("Timeline labels distinguish whole-block edits from individual step edits",delegate{
                using(var form=new MainForm(Samples.Nested(),null,false,false,true)){Render(form,directory,"scope-controls");form.SelectHeadlessStep(0);Check(Button(form,"Delete").Text=="Delete block"&&Button(form,"Enable / disable").Text=="Disable block","Block scope is unclear");form.SelectHeadlessStep(1);Check(Button(form,"Delete").Text=="Delete"&&Button(form,"Enable / disable").Text=="Disable step","Single-step controls retained block labels");}
            });
            test("Guide center searches actions and recipes and recovers from empty results",delegate{
                using(var guide=new GuideCenter(ActionKind.IfImage)){Click(Button(guide,"Pause guide"));Click(Button(guide,"Image missing"));Check(Button(guide,"Pause guide").Text=="Pause"&&!All(guide).OfType<ActionShowcase>().Single().Paused,"Changing a scenario retained a stale pause label");int count=guide.TopicCount;Check(count>30,"Action reference is incomplete");guide.SearchHeadless("END IF");Check(guide.TopicCount>0,"Block boundaries have no guide");guide.SearchHeadless("nested");Check(guide.TopicCount>0,"Nested recipe not discoverable");guide.SearchHeadless("no-such-guide-938481");Check(guide.TopicCount==0,"Unmatched search retained stale results");guide.SearchHeadless("image");Check(guide.TopicCount>=4,"Image reference missing");guide.SearchHeadless("");Check(guide.TopicCount==count&&!guide.Visible,"Search recovery changed inventory or showed a window");}
            });
            test("Reference workspace renders compact and wide in every palette without timers",delegate{
                foreach(string style in UiTheme.Styles)foreach(bool dark in new[]{false,true}){UiTheme.Style=style;UiTheme.Dark=dark;using(var guide=new GuideCenter(ActionKind.IfImage)){foreach(int width in new[]{940,1180}){guide.Size=new Size(width,750);Render(guide,directory,"guide-center-"+style+"-"+dark+"-"+width);var drawing=All(guide).OfType<ActionShowcase>().Single();Check(drawing.Width>550&&drawing.Height==drawing.IllustrationHeight&&!drawing.AnimationRunning,"Guide is clipped or starts a hidden timer");var reader=All(guide).Single(c=>c.AccessibleName=="Guide reading area");Check(reader.ClientSize.Height>350,"Reading viewport collapsed");}guide.SearchHeadless("nested");Render(guide,directory,"guide-recipe-"+style+"-"+dark);}}UiTheme.Style="Aftershock";UiTheme.Dark=true;
            });
            test("Animated stage scrubber and keyboard pause without touching desktop input",delegate{
                using(var drawing=new ActionShowcase(ActionKind.IfImage)){drawing.Width=840;var down=typeof(ActionShowcase).GetMethod("OnMouseDown",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);down.Invoke(drawing,new object[]{new MouseEventArgs(MouseButtons.Left,1,700,15,0)});Check(drawing.Phase==3&&drawing.Paused&&!drawing.AnimationRunning,"Click did not inspect the selected stage");var key=typeof(ActionShowcase).GetMethod("OnKeyDown",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic);key.Invoke(drawing,new object[]{new KeyEventArgs(Keys.Left)});Check(drawing.Phase==2&&drawing.Paused,"Arrow did not scrub backward");key.Invoke(drawing,new object[]{new KeyEventArgs(Keys.Space)});Check(!drawing.Paused&&!drawing.AnimationRunning,"Space started a hidden timer");}
            });
            test("Animated walkthroughs advance deterministically without starting a headless timer",delegate{
                foreach(ActionKind kind in new[]{ActionKind.IfImage,ActionKind.ClickImage,ActionKind.Repeat,ActionKind.Launch})using(var guide=new ActionShowcase(kind)){guide.Width=840;guide.Paused=true;var hashes=new List<int>();foreach(int frame in new[]{0,3000,5400,8400}){guide.Seek(frame);Check(guide.Phase==frame/2400&&!guide.AnimationRunning,"Incorrect animation phase or a headless timer started");using(var bitmap=new Bitmap(guide.Width,guide.Height)){guide.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));int hash=17;for(int y=0;y<bitmap.Height;y+=7)for(int x=0;x<bitmap.Width;x+=7)hash=unchecked(hash*31+bitmap.GetPixel(x,y).ToArgb());hashes.Add(hash);}}Check(hashes.Distinct().Count()==4,"Animation phases paint identical frames: "+kind);guide.Replay();Check(guide.Playhead==0&&!guide.Paused&&!guide.AnimationRunning,"Replay did not reset safely");}
            });
            test("Pause and replay controls leave the real macro draft untouched",delegate{
                using(var form=new StepEditor(new Step{Kind=ActionKind.IfImage},directory)){string original=Storage.Serializer().Serialize(form.Value);Click(Button(form,"Toggle action example"));Click(Button(form,"Pause or play example animation"));var guide=All(form).OfType<ActionShowcase>().Single();guide.Seek(5400);Check(guide.Paused&&guide.Phase==2,"Pause state lost");Click(Button(form,"Replay example animation"));Check(guide.Playhead==0&&!guide.Paused&&!guide.AnimationRunning&&original==Storage.Serializer().Serialize(form.Value),"Animation changed the action or ran a hidden timer");}
            });
            test("Visual guide has a dedicated workspace and returns to unchanged settings",delegate{
                using(var form=new StepEditor(new Step{Kind=ActionKind.IfImage},directory)){string before=Storage.Serializer().Serialize(form.Value);var toggle=Button(form,"Toggle action example");Click(toggle);var root=(TableLayoutPanel)toggle.Parent.Parent;Check(root.RowStyles[1].SizeType==SizeType.Percent&&root.RowStyles[2].SizeType==SizeType.Absolute&&root.RowStyles[2].Height==0,"Guide still competes with the settings viewport");Click(Button(form,"Example scenario: Image missing"));Click(Button(form,"Back from visual guide"));Check(root.RowStyles[1].SizeType==SizeType.Absolute&&root.RowStyles[2].SizeType==SizeType.Percent,"Back did not restore the editor");Check(before==Storage.Serializer().Serialize(form.Value),"Viewing the guide modified real settings");}
            });
            test("Escape returns from the guide without cancelling or changing the action",delegate{
                using(var form=new StepEditor(new Step{Kind=ActionKind.Launch,Target="notepad.exe"},directory)){Click(Button(form,"Toggle action example"));var method=typeof(StepEditor).GetMethod("ProcessCmdKey",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);var args=new object[]{new Message(),Keys.Escape};Check((bool)method.Invoke(form,args)&&form.DialogResult==DialogResult.None&&form.Value.Target=="notepad.exe","Escape closed or edited the draft");Check(((TableLayoutPanel)Button(form,"Toggle action example").Parent.Parent).RowStyles[2].SizeType==SizeType.Percent,"Escape failed to restore settings");}
