            test("First-open and repeated expansion lay out every guide without preview preparation",delegate{
                foreach(ActionKind kind in Enum.GetValues(typeof(ActionKind)))using(var form=new StepEditor(new Step{Kind=kind},directory)){
                    var handle=form.Handle;form.PerformLayout();var guide=All(form).OfType<ActionShowcase>().Single();var content=All(form).Single(c=>c.AccessibleName=="Visual example content");var host=All(form).OfType<Panel>().Single(c=>c.AccessibleName=="Visual example guide");
                    foreach(int width in new[]{920,650,1100,650}){form.Size=new Size(width,width==650?600:900);Click(Button(form,"Toggle action example"));Check(guide.Width>=400&&guide.Height==guide.IllustrationHeight,"First-open guide has no usable size: "+kind);Check(content.Height>=guide.Bottom&&content.ClientRectangle.Contains(guide.Bounds)&&host.AutoScrollMinSize.Height>=guide.Bottom,"Guide is outside its content/scroll range: "+kind);Click(Button(form,"Toggle example explanation"));Click(Button(form,"Toggle example explanation"));Click(Button(form,"Toggle action example"));}
                    Check(!form.Visible,"Expansion showed a desktop window");
                }
            });
            test("Image guide first expansion paints both branches after the editor is already initialized",delegate{
                using(var form=new StepEditor(Samples.Nested().Steps[0],directory)){
                    // Initial render leaves the guide collapsed. Expand only afterwards.
                    Render(form,directory,"if-guide-before-open");var guide=All(form).OfType<ActionShowcase>().Single();var toggle=Button(form,"Toggle action example");
                    foreach(int width in new[]{920,650,1000}){form.Size=new Size(width,width==650?600:900);Click(toggle);foreach(string scenario in new[]{"Image found","Image missing"}){Click(Button(form,"Example scenario: "+scenario));Render(form,directory,"if-guide-"+width+"-"+scenario.Replace(" ","-"));using(var bitmap=new Bitmap(guide.Width,guide.Height)){guide.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));foreach(var panel in new[]{guide.SetupBounds,guide.OutcomeBounds}){int samples=0;Color backgroundSample=bitmap.GetPixel(panel.X+10,panel.Y+10);for(int y=panel.Top+12;y<panel.Bottom-12;y+=3)for(int x=panel.Left+12;x<panel.Right-12;x+=3)if(bitmap.GetPixel(x,y).ToArgb()!=backgroundSample.ToArgb())samples++;Check(samples>100,"Guide panel painted blank: "+scenario);}}}Click(toggle);}
                    Check(!form.Visible,"Image guide showed a window");
                }
            });
            test("Reopening a scrolled image example returns to its visible illustration",delegate{
                using(var form=new StepEditor(Samples.Nested().Steps[0],directory)){form.Size=form.MinimumSize;Render(form,directory,"if-help-scroll-start");var host=All(form).OfType<Panel>().Single(c=>c.AccessibleName=="Visual example guide");Click(Button(form,"Help: Reference image"));host.AutoScrollPosition=new Point(0,10000);Click(Button(form,"Toggle action example"));Click(Button(form,"Toggle action example"));Check(host.AutoScrollPosition.Y==0,"Reopened guide retained a stale scroll position");var guide=All(form).OfType<ActionShowcase>().Single();Check(guide.Top<host.ClientSize.Height&&guide.Width>400,"Reopened guide is outside the viewport");Render(form,directory,"if-help-scroll-reopened");Check(!form.Visible,"Scroll regression showed the desktop");}
