                foreach(ActionKind kind in Enum.GetValues(typeof(ActionKind)))using(var guide=new ActionShowcase(kind)){foreach(int width in new[]{800,540}){guide.Width=width;using(var bitmap=new Bitmap(width,guide.Height))guide.DrawToBitmap(bitmap,new Rectangle(Point.Empty,bitmap.Size));Check(guide.Scene.Fields.Length>0&&guide.Scene.Outcome.Length>12,"Missing showcase content for "+kind);Check(guide.ClientRectangle.Contains(guide.SetupBounds)&&guide.ClientRectangle.Contains(guide.OutcomeBounds),"Illustration clipped for "+kind);Check(width==800?guide.SetupBounds.Right<guide.OutcomeBounds.Left:guide.SetupBounds.Bottom<guide.OutcomeBounds.Top,"Incorrect responsive layout");}}
