            test("Example scenarios switch only the illustration and retain the configured action",delegate{
                using(var form=new StepEditor(new Step{Kind=ActionKind.Launch,Target="my-program.exe",Text="--keep"},directory)){string before=Storage.Serializer().Serialize(form.Value);var guide=All(form).OfType<ActionShowcase>().Single();Click(Button(form,"Example scenario: Document"));Check(guide.Scene.Title.Contains("report.pdf"),"Document showcase missing");Click(Button(form,"Example scenario: Script"));Check(guide.Scene.Fields.Any(f=>f.Contains("python.exe")),"Script showcase missing");Click(Button(form,"Example scenario: Program"));Check(guide.Scene.Title.Contains("Notepad")&&before==Storage.Serializer().Serialize(form.Value),"Showcase edited the real action");}
                using(var form=new StepEditor(new Step{Kind=ActionKind.IfImage},directory)){Click(Button(form,"Example scenario: Image missing"));var guide=All(form).OfType<ActionShowcase>().Single();Check(guide.Scene.Art=="missing"&&guide.Scene.Outcome.Contains("ELSE"),"Missing image shows wrong branch");Click(Button(form,"Example scenario: Image found"));Check(guide.Scene.Art=="image"&&guide.Scene.Outcome.Contains("IF branch")&&!guide.Scene.Outcome.Contains("click"),"IF falsely implies an automatic click");}
