                foreach(ActionKind kind in Enum.GetValues(typeof(ActionKind))){Check(ActionExamples.For(kind).Length>40,"Missing example for "+kind);var source=new Step{Kind=kind};using(var form=new StepEditor(source,directory)){string before=Storage.Serializer().Serialize(form.Value);var toggle=Button(form,"Toggle action example");var text=All(form).OfType<TextBox>().Single(t=>t.AccessibleName=="Action usage example");Check(toggle.Parent.Parent is TableLayoutPanel&&((TableLayoutPanel)toggle.Parent.Parent).GetRow(toggle.Parent)==1,"Example moved for "+kind);Click(toggle);Check(text.Text==ActionExamples.For(kind)&&toggle.AccessibleDescription.StartsWith("Expanded"),"Wrong expanded example for "+kind);Click(toggle);Check(toggle.Text.Contains("How to use")&&Storage.Serializer().Serialize(form.Value)==before,"Help changed action values for "+kind);}}
