                bool oldDark=UiTheme.Dark;string oldStyle=UiTheme.Style;try{foreach(string style in UiTheme.Styles)foreach(bool dark in new[]{false,true}){UiTheme.Style=style;UiTheme.Dark=dark;foreach(ActionKind kind in new[]{ActionKind.Launch,ActionKind.IfImage,ActionKind.Repeat,ActionKind.TypeText})using(var form=new StepEditor(new Step{Kind=kind},directory)){form.Size=form.MinimumSize;Click(Button(form,"Toggle action example"));Render(form,directory,"example-"+kind+"-"+style+"-"+dark);var save=Button(form,"Back from visual guide");Check(save.Width>=100&&save.Height>=30&&save.Parent.ClientRectangle.Contains(save.Bounds),"Example clipped save button");var cancel=Button(form,"Cancel");Check(cancel.Parent.ClientRectangle.Contains(cancel.Bounds),"Cancel is clipped in guide mode");var explanation=Button(form,"Toggle example explanation");Check(explanation.Parent.ClientRectangle.Contains(explanation.Bounds),"Compact scenario bar clips Explanation");Check(!form.Visible,"Example showed a window");}}}finally{UiTheme.Dark=oldDark;UiTheme.Style=oldStyle;}
