            });
            test("Workflow browse uses an injected chooser without loading or playing",delegate{
                int calls=0;using(var form=new WorkflowPicker(new string[0],delegate{calls++;return one;})){Click(Button(form,"Browse files…"));Check(calls==1&&form.SelectedPath==one&&form.DialogResult==DialogResult.OK,"Browse selection lost");}
            });
            test("Binding cards edit the correct slot and never mutate source settings",delegate{
                var source=new[]{one};using(var form=new WorkflowBindingsForm(source,Shortcuts.Defaults(),delegate{return two;})){Click(Button(form,"Choose workflow 9"));Check(form.Value[8]==two&&source[0]==one,"Wrong slot or aliased input");Click(Button(form,"Clear workflow 1"));Click(Button(form,"Save bindings"));Check(form.Value[0]==""&&form.Value[8]==two&&source[0]==one&&form.DialogResult==DialogResult.OK,"Clearing lost another binding or edited source");}
            });
            test("Binding conflicts remain inline and keep the editor open",delegate{
                var shortcuts=Shortcuts.Defaults();var record=shortcuts.Single(s=>s.Command==AppCommand.Record);record.Key=(int)Keys.D1;record.Modifiers=(int)(Keys.Control|Keys.Alt);
                using(var form=new WorkflowBindingsForm(new[]{one},shortcuts,delegate{return null;})){Click(Button(form,"Save bindings"));Check(form.DialogResult==DialogResult.None&&All(form).OfType<Label>().Single(l=>l.AccessibleName=="Binding validation").Text.Length>0,"Conflict closed editor or used a modal error");}
            });
            test("Shortcut search retains unsaved key changes and saves the complete set",delegate{
                Shortcut[] saved=null;using(var form=new ShortcutForm(Shortcuts.Defaults(),new string[0],delegate(Shortcut[] value){saved=value;return null;})) {
                    var box=All(form).OfType<ShortcutBox>().Single(b=>b.Binding.Command==AppCommand.Record);typeof(Control).GetMethod("OnKeyDown",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance).Invoke(box,new object[]{new KeyEventArgs(Keys.Control|Keys.Shift|Keys.R)});
                    All(form).OfType<TextBox>().Single(t=>t.AccessibleName=="Search keyboard shortcuts").Text="stop";Check(!Button(form,"Clear "+Shortcuts.Name(AppCommand.Stop)).Enabled,"Stop can be cleared");Click(Button(form,"Save shortcuts"));Check(saved!=null&&saved.Length==Shortcuts.Defaults().Length&&saved.Single(s=>s.Command==AppCommand.Record).Chord==(Keys.Control|Keys.Shift|Keys.R),"Search discarded a hidden shortcut");
                }
            });
            test("Shortcut save errors remain inline without a modal dialog",delegate{
                using(var form=new ShortcutForm(Shortcuts.Defaults(),new string[0],delegate{return "Already reserved by another application";})){Click(Button(form,"Save shortcuts"));Check(form.DialogResult==DialogResult.None&&All(form).OfType<Label>().Single(l=>l.AccessibleName=="Shortcut feedback").Text.Contains("reserved"),"Save failure was lost or closed editor");}
            });
            test("All palettes render compact in light and dark with reachable footers",delegate{
                bool original=UiTheme.Dark;string originalStyle=UiTheme.Style;try{foreach(string style in UiTheme.Styles)foreach(bool dark in new[]{false,true}){UiTheme.Dark=dark;UiTheme.Style=style;using(var settings=new PreferencesForm(new Preferences{DarkMode=dark,AccentStyle=style}))using(var bindings=new WorkflowBindingsForm(new[]{one},Shortcuts.Defaults(),delegate{return null;}))using(var picker=new WorkflowPicker(new[]{one,two},delegate{return null;}))using(var shortcuts=new ShortcutForm(Shortcuts.Defaults(),new string[0],delegate{return null;})){foreach(var form in new Form[]{settings,bindings,picker,shortcuts}){form.Size=form.MinimumSize;Render(form,directory,form.GetType().Name+"-compact-"+dark);var button=Button(form,form is PreferencesForm?"Save preferences":form is WorkflowBindingsForm?"Save bindings":form is WorkflowPicker?"Open selected":"Save shortcuts");Check(button.Width>80&&button.Parent.ClientRectangle.Contains(button.Bounds),"Primary footer is clipped in "+form.GetType().Name);}}}}finally{UiTheme.Dark=original;UiTheme.Style=originalStyle;}
            });
        }
    }
}
